#include <string.h>

bool canTransform(const char* start, const char* result) {
    size_t i = 0, j = 0;
    size_t n = strlen(start);

    while (i < n || j < n) {
        while (i < n && start[i] == 'X') i++;
        while (j < n && result[j] == 'X') j++;

        if (i == n || j == n) return i == n && j == n;
        if (start[i] != result[j]) return false;
        if (start[i] == 'L' && i < j) return false;
        if (start[i] == 'R' && i > j) return false;

        i++;
        j++;
    }

    return true;
}

static int readQuoted(const char* p, char* out, int cap) {
    const char* q1 = strchr(p, '"');
    if (!q1) return 0;
    q1++;
    int len = 0;
    while (*q1 && *q1 != '"') {
        if (len + 1 >= cap) return 0;
        out[len++] = *q1++;
    }
    if (*q1 != '"') return 0;
    out[len] = '\0';
    return (int)(q1 - p + 1);
}

int main(void) {
    char line[20050];
    char start[10001], result[10001];

    if (!fgets(line, sizeof(line), stdin)) return 0;

    const char* p = line;
    int used = readQuoted(p, start, (int)sizeof(start));
    if (!used) return 0;
    p += used;

    used = readQuoted(p, result, (int)sizeof(result));
    if (!used) return 0;

    printf("%s\n", canTransform(start, result) ? "true" : "false");
    return 0;
}

