};

static pair<string, string> parseArgs(const string& line) {
    vector<size_t> quotes;
    for (size_t i = 0; i < line.size(); ++i) {
        if (line[i] == '"') quotes.push_back(i);
    }
    return {
        line.substr(quotes[0] + 1, quotes[1] - quotes[0] - 1),
        line.substr(quotes[2] + 1, quotes[3] - quotes[2] - 1)
    };
}

