import java.io.*;

class Solution {
    public boolean canTransform(String start, String result) {
        int i = 0, j = 0;
        int n = start.length();

        while (i < n || j < n) {
            while (i < n && start.charAt(i) == 'X') i++;
            while (j < n && result.charAt(j) == 'X') j++;

            if (i == n || j == n) return i == n && j == n;
            if (start.charAt(i) != result.charAt(j)) return false;
            if (start.charAt(i) == 'L' && i < j) return false;
            if (start.charAt(i) == 'R' && i > j) return false;

            i++;
            j++;
        }

        return true;
    }
}

public class Main {
    private static String[] parseArgs(String line) {
        int first = line.indexOf('"');
        int second = first + 1;
        while (second < line.length() && line.charAt(second) != '"') second++;
        int third = line.indexOf('"', second + 1);
        int fourth = third + 1;
        while (fourth < line.length() && line.charAt(fourth) != '"') fourth++;
        String start = line.substring(first + 1, second);
        String result = line.substring(third + 1, fourth);
        return new String[]{start, result};
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] values = parseArgs(line.trim());
        boolean answer = new Solution().canTransform(values[0], values[1]);
        System.out.println(answer ? "true" : "false");
    }
}

